2	// preconditions.mjs) — the cheap gate the scheduler runs in code before anything
3	// else exists. Its whole job is eligibility over the
4	// `issues` signal; everything it must NOT do (parse a body, classify a host, close
5	// anything) belongs to preprocessing, and the absence of that here is the point of
6	// the split, so it is worth asserting the gate stays that shape.
7	"use strict";
8	
9	const { test } = require("node:test");
10	const assert = require("node:assert/strict");
11	
12	const load = async () => {
13	  const { terms } = await import("../preconditions.mjs");
14	  return terms["extractor-request-eligible"];
15	};
16	
17	const signals = (open) => ({ issues: { open, touched: [] } });
18	const req = (number, labels = ["extractor-request"]) => ({ number, title: `Event source request - #${number}`, labels });
19	
20	test("no open request and no page churn → skip, with a reason a human can read in the job summary", async () => {
21	  const term = await load();
22	  const v = term.holds(signals([]));
23	  assert.equal(v.holds, false);
24	  assert.match(v.reason, /no open extractor-request issue is eligible/);
25	});
26	
27	test("no request, but a cached-page file moved → run anyway, to sweep for a page needing a record", async () => {
28	  const term = await load();
29	  const v = term.holds({
30	    issues: { open: [] },
31	    commits: { touchedPaths: ["dev/requirements/extractor/data/server-fetched/dice.url"] },
32	  });
33	  assert.equal(v.holds, true);
34	  assert.match(v.reason, /sweep for a page needing a record/);
35	});
