37	test("a commit elsewhere is not a reason to run", async () => {
38	  const term = await load();
39	  const v = term.holds({ issues: { open: [] }, commits: { touchedPaths: ["extension/popup.js"] } });
40	  assert.equal(v.holds, false);
41	});
42	
43	test("an unrelated open issue is not a request", async () => {
44	  const term = await load();
45	  assert.equal(term.holds(signals([req(3, ["bug"])])).holds, false);
46	});
