75	  const task = (await import("../task.mjs")).default;
76	  assert.equal(task.id, "create-extractor");
77	  // `daily`, not `hourly`: the canon retired that token and normalizes it away at the
78	  // declaration door, so this task has run daily since — and #1060 accepts a slow cycle
79	  // until an event trigger replaces the poll. Pinned so the declaration cannot drift back
80	  // to a cadence the queue will not honour.
81	  assert.equal(task.frequency, "daily");
82	  // The declarative expression is the ONLY gate mechanism: the `precondition`
83	  // function and its `precondition_signals` companion are retired, and the signal
84	  // union is DERIVED from the term rather than restated here
85	  // (missingbulb/Claudinite#1617).
