87	  assert.equal(task.precondition, undefined);
88	  assert.equal(task.precondition_signals, undefined);
89	  // The pair the canon's auto-merge contract splits the old `open-pr` ceiling into:
90	  // a run may open a PR, and nothing it produces may land without a person.
91	  assert.equal(task.expected_outcome, "pr");
92	  assert.equal(task.automerge, "nothing");         // a human always reviews the extraction
93	  assert.equal(task.agent_preprocessing, "node prepare.mjs");
94	  assert.deepEqual(task.required_secrets, ["SCRAPER_API_KEY"]);
95	  assert.ok(task.agent_preprocessing_timeout > 0 && task.agent_execution_timeout > 0);
96	});
