101	  const v = term.holds({ issues: { open: [{ number: 1, title: "t", labels: ["extractor-request"] }] } });
102	  assert.equal(v.holds, true);
103	  // And a missing signal must not throw — a collector error can't sink the gate.
104	  assert.equal(term.holds({}).holds, false);
105	});
